using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Diagnostics;using System.Threading;using System.Collections.Generic;using System.Windows.Forms;using System.Security.Cryptography;using System.Web.Script.Serialization;
namespace GearLab {
 public sealed partial class WpfScene {internal object PerformanceEnvironment{get{return environment.Content;}}}
 public static class PerformanceTests {
  static IEnumerable<Control> All(Control c){yield return c;foreach(Control child in c.Controls)foreach(var n in All(child))yield return n;}
  static object Measure(string name,int count,Action action){action();var samples=new List<double>();int g0=GC.CollectionCount(0);for(int i=0;i<count;i++){var clock=Stopwatch.StartNew();action();samples.Add(clock.Elapsed.TotalMilliseconds);}samples.Sort();return new{name=name,iterations=count,median_ms=samples[samples.Count/2],p95_ms=samples[Math.Min(samples.Count-1,(int)(samples.Count*.95))],gen0_collections=GC.CollectionCount(0)-g0};}
  internal static string Fingerprint(SceneMesh mesh){using(var memory=new MemoryStream())using(var writer=new BinaryWriter(memory)){foreach(var p in mesh.Points){writer.Write(p.X);writer.Write(p.Y);writer.Write(p.Z);}foreach(var n in mesh.Normals){writer.Write(n.X);writer.Write(n.Y);writer.Write(n.Z);}foreach(var i in mesh.Indices)writer.Write(i);writer.Flush();using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(memory.ToArray())).Replace("-","");}}
  public static int Run(string folder){Directory.CreateDirectory(folder);Environment.SetEnvironmentVariable("GEARLAB_PROFILE_DIR",Path.GetFullPath(Path.Combine(folder,"profile")));var results=new List<object>();var invariants=new List<object>();try{AppSettings.Commit(new AppSettings());var startup=Stopwatch.StartNew();using(var first=new MainForm()){first.Show();Application.DoEvents();startup.Stop();results.Add(new{name="first_reducer_window",iterations=1,median_ms=startup.Elapsed.TotalMilliseconds});first.WorkspaceApproveClose();first.Close();}
   results.Add(Measure("palette_10000",7,()=>{for(int i=0;i<10000;i++)UiPalette.Get(UiPalette.Keys[i%UiPalette.Keys.Length]);}));AppSettings.SetLanguage(GearLanguage.English);results.Add(Measure("english_ascii_10000",7,()=>{for(int i=0;i<10000;i++)I18n.T("Frame all · Speed 0.10 · X 125.25 mm");}));results.Add(Measure("translated_status_2000",7,()=>{for(int i=0;i<2000;i++)I18n.T("Параметр "+(i%100)+": Габарит 80 мм; Выход 30 об/мин");}));AppSettings.SetLanguage(GearLanguage.Русский);
   foreach(int kind in new[]{0,3,4,7}){int k=kind;results.Add(Measure("calculate_family_"+k,5,()=>Engine.Calculate(Engine.Starter(k))));results.Add(Measure("model_family_"+k,5,()=>{var r=Engine.Calculate(Engine.Starter(k));var model=CadBuilder.Build(r);if(!model.Valid)throw new Exception("Invalid benchmark model "+k);}));}
   var sphere=new AnalyticSolid{Sphere=new[]{12.25,-3.5,4.75,2.15}};var race=new AnalyticSolid{Revolve=new[]{new[]{3.0,-1.0},new[]{5.0,-1.0},new[]{5.0,2.0},new[]{3.0,2.0}}};results.Add(Measure("sphere_50",5,()=>{for(int i=0;i<50;i++)sphere.Mesh();}));results.Add(Measure("revolve_50",5,()=>{for(int i=0;i<50;i++)race.Mesh();}));foreach(double radius in new[]{.0001,.1,2.15,1000})invariants.Add(new{shape="sphere",radius=radius,hash=Fingerprint(new AnalyticSolid{Sphere=new[]{12.25,-3.5,4.75,radius}}.Mesh())});invariants.Add(new{shape="revolve",radius=0.0,hash=Fingerprint(race.Mesh())});
   using(var form=new MainForm()){form.Show();Application.DoEvents();int invalidations=0;foreach(var c in All(form))c.Invalidated+=(s,e)=>invalidations++;results.Add(Measure("reapply_existing_ui",5,()=>AppSettings.Apply(form)));int calls=0;results.Add(Measure("speed_change_open_editor",7,()=>{AppSettings.SetAnimationSpeed((++calls%2)==0?.25:.5);}));invariants.Add(new{scenario="ui_invalidations",count=invalidations});form.WorkspaceApproveClose();form.Close();}
   var value=Engine.Calculate(Engine.Starter(4));value.Model=CadBuilder.Build(value);using(var scene=new WpfScene()){scene.SetResult(value,false);results.Add(Measure("ptk_pose_60_frames",5,()=>{for(int i=0;i<60;i++)scene.UpdatePose(i*.03);}));var before=scene.PerformanceEnvironment;int calls=0;results.Add(Measure("speed_change_with_3d",7,()=>AppSettings.SetAnimationSpeed((++calls%2)==0?.3:.6)));invariants.Add(new{scenario="speed_preserves_environment",preserved=ReferenceEquals(before,scene.PerformanceEnvironment)});}
   var report=new{version=ReleaseSupport.Version,machine=Environment.MachineName,processors=Environment.ProcessorCount,framework=Environment.Version.ToString(),results=results,invariants=invariants,peak_working_set=Process.GetCurrentProcess().PeakWorkingSet64};File.WriteAllText(Path.Combine(folder,"performance-results.json"),new JavaScriptSerializer().Serialize(report),Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"performance-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}}
 }
}
